// GET /sitemap.xml  (also /api/sitemap) and GET /robots.txt on the Render host.
//
// There is ONE real sitemap and it lives with the pages it lists:
//   https://lexdendigital.github.io/LEXDEN-NOVA/sitemap.xml
// It is generated by scripts/generate-sitemap.js (see the sync workflow). Google only
// trusts a sitemap for URLs on its own host, so this server no longer publishes a
// second, competing list of onrender.com URLs. Anything that still asks here is
// sent to the real one with a permanent redirect.
const SITEMAP_URL = 'https://lexdendigital.github.io/LEXDEN-NOVA/sitemap.xml';

function handler(req, res) {
  res.setHeader('Cache-Control', 'public, max-age=3600');
  return res.redirect(301, SITEMAP_URL);
}

function robots(req, res) {
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.status(200).send(`User-agent: *\nAllow: /\n\nSitemap: ${SITEMAP_URL}\n`);
}

module.exports = handler;
module.exports.robots = robots;
module.exports.SITEMAP_URL = SITEMAP_URL;
